import { NextRequest, NextResponse } from "next/server";

// The reset token is generated by the Express API (it logs the reset URL in
// development and e-mails it when SMTP is configured). Forward the request there
// instead of pretending a link was sent.
const API_URL = process.env.NEXT_PUBLIC_API_URL || "http://localhost:5010";

const GENERIC_MESSAGE =
  "If an account exists with this email, you will receive a password reset link.";

export async function POST(req: NextRequest) {
  try {
    const { email } = await req.json();

    if (!email || !/\S+@\S+\.\S+/.test(email)) {
      return NextResponse.json(
        { error: "Please provide a valid email address" },
        { status: 400 }
      );
    }

    const response = await fetch(`${API_URL}/api/v1/auth/forgot-password`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ email }),
    });

    if (!response.ok) {
      const data = await response.json().catch(() => ({}));
      return NextResponse.json(
        { error: data?.message || data?.error || "Could not start the password reset" },
        { status: response.status }
      );
    }

    // The API always answers generically, so the response never reveals whether
    // the account exists.
    return NextResponse.json({ success: true, message: GENERIC_MESSAGE });
  } catch (error) {
    return NextResponse.json(
      { error: "Could not reach the authentication service. Please try again." },
      { status: 502 }
    );
  }
}
